#include <stdlib.h>
#include <string.h>
#include <omp.h>

typedef float v8 __attribute__((vector_size(32)));

#define MR 6
#define NR 16
#define KC 256
#define MCP 16   /* row panels per tile  -> 96 rows   */
#define NCP 16   /* col panels per tile  -> 256 cols  */

static inline v8 ldv(const float *p) { v8 v; memcpy(&v, p, sizeof v); return v; }
static inline void stv(float *p, v8 v) { memcpy(p, &v, sizeof v); }

static void kernel(int kc, const float *restrict a, const float *restrict b,
                   float *restrict c, int ldc, int mr, int nr, int accum)
{
    v8 c00 = {0}, c01 = {0}, c10 = {0}, c11 = {0}, c20 = {0}, c21 = {0};
    v8 c30 = {0}, c31 = {0}, c40 = {0}, c41 = {0}, c50 = {0}, c51 = {0};

    for (int p = 0; p < kc; p++) {
        v8 b0 = *(const v8 *)(b + p * NR);
        v8 b1 = *(const v8 *)(b + p * NR + 8);
        const float *ap = a + p * MR;
        float a0 = ap[0], a1 = ap[1], a2 = ap[2], a3 = ap[3], a4 = ap[4], a5 = ap[5];
        c00 += b0 * a0; c01 += b1 * a0;
        c10 += b0 * a1; c11 += b1 * a1;
        c20 += b0 * a2; c21 += b1 * a2;
        c30 += b0 * a3; c31 += b1 * a3;
        c40 += b0 * a4; c41 += b1 * a4;
        c50 += b0 * a5; c51 += b1 * a5;
    }

    v8 acc[MR][2] = { {c00, c01}, {c10, c11}, {c20, c21},
                      {c30, c31}, {c40, c41}, {c50, c51} };

    if (mr == MR && nr == NR) {
        for (int r = 0; r < MR; r++) {
            float *cr = c + (size_t)r * ldc;
            if (accum) {
                stv(cr, ldv(cr) + acc[r][0]);
                stv(cr + 8, ldv(cr + 8) + acc[r][1]);
            } else {
                stv(cr, acc[r][0]);
                stv(cr + 8, acc[r][1]);
            }
        }
    } else {
        float tmp[MR][NR];
        for (int r = 0; r < MR; r++) {
            stv(&tmp[r][0], acc[r][0]);
            stv(&tmp[r][8], acc[r][1]);
        }
        for (int r = 0; r < mr; r++) {
            float *cr = c + (size_t)r * ldc;
            if (accum)
                for (int j = 0; j < nr; j++) cr[j] += tmp[r][j];
            else
                for (int j = 0; j < nr; j++) cr[j] = tmp[r][j];
        }
    }
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;

    int mp = (n + MR - 1) / MR;      /* row panels */
    int np = (n + NR - 1) / NR;      /* col panels */
    int kcmax = n < KC ? n : KC;

    size_t asz = (size_t)mp * MR * kcmax * sizeof(float);
    size_t bsz = (size_t)np * NR * kcmax * sizeof(float);
    asz = (asz + 63) & ~(size_t)63;
    bsz = (bsz + 63) & ~(size_t)63;
    float *Ap = aligned_alloc(64, asz);
    float *Bp = aligned_alloc(64, bsz);

    int mt = (mp + MCP - 1) / MCP;   /* row tiles */
    int nt = (np + NCP - 1) / NCP;   /* col tiles */
    int ntiles = mt * nt;

    #pragma omp parallel
    {
        for (int pc = 0; pc < n; pc += KC) {
            int kc = n - pc < KC ? n - pc : KC;
            int accum = pc > 0;

            #pragma omp for schedule(static) nowait
            for (int ip = 0; ip < mp; ip++) {
                float *dst = Ap + (size_t)ip * MR * kc;
                int i0 = ip * MR;
                int rows = n - i0 < MR ? n - i0 : MR;
                const float *src[MR];
                for (int r = 0; r < MR; r++)
                    src[r] = A + (size_t)(i0 + (r < rows ? r : 0)) * n + pc;
                for (int p = 0; p < kc; p++)
                    for (int r = 0; r < MR; r++)
                        dst[p * MR + r] = r < rows ? src[r][p] : 0.0f;
            }

            #pragma omp for schedule(static)
            for (int jp = 0; jp < np; jp++) {
                float *dst = Bp + (size_t)jp * NR * kc;
                int j0 = jp * NR;
                int cols = n - j0 < NR ? n - j0 : NR;
                for (int p = 0; p < kc; p++) {
                    const float *s = B + (size_t)(pc + p) * n + j0;
                    float *d = dst + p * NR;
                    if (cols == NR) {
                        memcpy(d, s, NR * sizeof(float));
                    } else {
                        int j = 0;
                        for (; j < cols; j++) d[j] = s[j];
                        for (; j < NR; j++) d[j] = 0.0f;
                    }
                }
            }
            /* implicit barrier: Ap and Bp ready */

            #pragma omp for schedule(dynamic, 1)
            for (int t = 0; t < ntiles; t++) {
                int ti = t / nt, tj = t % nt;
                int ip0 = ti * MCP, ip1 = ip0 + MCP < mp ? ip0 + MCP : mp;
                int jp0 = tj * NCP, jp1 = jp0 + NCP < np ? jp0 + NCP : np;
                for (int jp = jp0; jp < jp1; jp++) {
                    const float *bp = Bp + (size_t)jp * NR * kc;
                    int j0 = jp * NR;
                    int nr = n - j0 < NR ? n - j0 : NR;
                    for (int ip = ip0; ip < ip1; ip++) {
                        const float *ap = Ap + (size_t)ip * MR * kc;
                        int i0 = ip * MR;
                        int mr = n - i0 < MR ? n - i0 : MR;
                        kernel(kc, ap, bp, C + (size_t)i0 * n + j0, n, mr, nr, accum);
                    }
                }
            }
            /* implicit barrier before repacking */
        }
    }

    free(Ap);
    free(Bp);
}
